    "personality": "섬을 지키는 과잉 충성 경비대원. 아기 때 버려진 상처로 버림받을까 늘 불안하다.",
    "speech": "\"충성!\" \"~입니다!\" \"보고드립니다!\" 같은 군인식 존댓말. 불안하면 말끝이 작아진다.",
